pages.panneau.css:
*{box-sizing:border-box}
[hidden]{display:none!important}
body{padding:12px 14px;font-size:13.5px}
.onglets{display:flex;flex-wrap:wrap;gap:6px 8px;margin-bottom:14px}
.onglets button{border-radius:999px;padding:4px 12px;font-weight:500;color:#1f2a26;border-color:#d6dbd7}
.onglets button[aria-selected="true"]{background:#1b4d42;border-color:#1b4d42;color:#fff;font-weight:600}
.formulaire{display:grid;grid-template-columns:1fr minmax(0,150px);gap:8px 12px;align-items:center;margin:0 0 12px}
.formulaire label{color:#1f2a26}
.formulaire input,.formulaire select{width:100%;border:1px solid #b9c5bd;border-radius:6px;padding:6px 8px;font:inherit;background:#fff;color:#1f2a26}
.resultats{display:grid;grid-template-columns:auto 1fr;gap:6px 12px;margin:0 0 12px}
.resultats dt{color:#1f2a26}
.resultats dd{margin:0;text-align:right;font-weight:600;font-variant-numeric:tabular-nums}
.resultats dd.ok{color:#1e7b3c}
.resultats dd.alerte{color:#b3261e}
.barre{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px}
button{border:1px solid #b9c5bd;border-radius:8px;padding:6px 10px;font:inherit;font-weight:600;color:#1b4d42;background:#fff;cursor:pointer}
.barre button.principal{background:#1b4d42;border-color:#1b4d42;color:#fff}
button:disabled{opacity:.45;cursor:default}
button:focus-visible,tr:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #2f6fd6;outline-offset:1px}
.encart{font-size:12.5px;color:#4d665f;background:#f1f4f2;border-radius:6px;padding:6px 8px;margin:0 0 10px}
.aide{color:#4d665f;margin:0}
.note{font-size:12px;color:#6a746f;margin:12px 0 0}
table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}
th{font-size:11.5px;color:#6a746f;text-align:left;font-weight:600;padding:4px 6px;border-bottom:1px solid #d6dbd7}
td{padding:5px 6px;border-bottom:1px solid #eef0ee}
.n{text-align:right;white-space:nowrap}
tr.groupe td{background:#f1f4f2;font-weight:600;color:#1b4d42}
tr[data-id]{cursor:pointer}
tr.ligne:hover td{background:#f6f8f6}
tr.choisi td{background:#dbe8fb}
tr.introuvable td{color:#9b3b17;background:#fdf1ea;font-size:12.5px}
tfoot td{font-weight:700;border-top:2px solid #1b4d42;border-bottom:0}
.pagination{display:flex;align-items:center;justify-content:center;gap:10px;margin-top:8px}
#erreur{margin:8px 0 0;font-size:12.5px;color:#b3261e}
.resultats dd.limite,td.limite{color:#8a6100;font-weight:600}
td.ok{color:#1e7b3c;font-weight:600}
td.alerte{color:#9b3b17;font-weight:600}
tr.hors td{background:#fdf1ea;color:#9b3b17}
#table{margin-bottom:12px}
#barre{margin-top:4px}

